import { ThemeToggle } from '../shared/theme/ThemeToggle';
import { lazy, Suspense, useState } from 'react';
import { createMappingServices } from './services';
import { MappingPocPage } from "../features/mapping/MappingPage";

const EvalsPage = lazy(() => import('../features/mapping/evals/EvalsPage').then(module => ({ default: module.EvalsPage })));
/** Unknown legacy entry paths continue to open Mapping. */
export function App() {
  const [services] = useState(createMappingServices);
  const evals = typeof window !== 'undefined' && window.location.pathname.replace(/\/$/, '') === `${import.meta.env.BASE_URL}evals`.replace(/\/$/, '');
  return <>{evals ? <Suspense fallback={<p>Loading Evals…</p>}><EvalsPage services={services} /></Suspense> : <MappingPocPage services={services} />}<ThemeToggle /></>;
}

import type { DisplayState } from './displayModel';
import { emptyDisplayState } from './displayModel';
import type { MappingGridDocument } from './mappingGrid';
import type { SelectionState } from '../selection/selectionState';
import type { CanvasTransform } from '../../core/diagrams/diagramCanvas';

/** Control surfaces are persisted separately from the display ownership tree. */
export interface SelectionSurfaceState {
  actionsOpen: boolean;
  presentation: 'compact' | 'floating' | 'docked';
  projectionChoice: string;
  promptOperation: 'edit' | 'generate';
  promptOpen: boolean;
  promptText: string;
  askOpen: boolean;
  askText: string;
  askVerbosity: "low" | "high";
  promptPhase: 'ready' | 'composing' | 'generating' | 'applied' | 'error';
  statusMessage: string;
}
export const selectionSurfaceKeys = ['actionsOpen', 'presentation', 'projectionChoice', 'promptOperation', 'promptOpen', 'promptText',
  'askOpen', 'askText', 'askVerbosity', 'promptPhase', 'statusMessage'] as const;
export const initialSelectionSurface = (): SelectionSurfaceState => ({ actionsOpen: true, presentation: 'compact', projectionChoice: '', promptOperation: 'edit',
  promptOpen: false, promptText: '', askOpen: false, askText: '', askVerbosity: 'low', promptPhase: 'ready', statusMessage: 'Ctrl + drag to select' });
export interface MappingControls {
  activeBoxId: string;
  /** Action-menu focus only; selection membership lives in selection.items. */
  selectionFocusId: string | null;
  activeThreadId: string | null;
  surfaces: Record<string, SelectionSurfaceState>;
}
/** A control accessor resolves these values against the active selection's surface. */
export type MappingControlValues = MappingControls & SelectionSurfaceState;
export interface MappingCanvasState { viewport?: CanvasTransform; projectionLayout?: import('../../core/diagrams/highlightProjection').ProjectionLayout; selection: SelectionState; diagramViews?: import('./diagramViewState').DiagramViews; display: DisplayState; controls: MappingControls }
export function initialCanvasState(): MappingCanvasState {
  return { selection: { items: [] }, diagramViews: {}, display: emptyDisplayState(), controls: { activeBoxId: 'overview', selectionFocusId: null, activeThreadId: null, surfaces: { draft: initialSelectionSurface() } } };
}
export interface MappingDocumentSnapshot {
  /** Missing on legacy snapshots; normalized to standard or projection on read. */
  type?: import('../../core/diagrams/canvasType').CanvasType;
  hidden?: boolean;
  history?: import('./canvasHistory').CanvasHistoryRecord;
  repositoryId?: string;
  savedRepresentationId?: string;
  representationId: string; name: string; revisionId: string; savedName: string; savedScene: string; savedEdges?: string;
  document: MappingGridDocument; canvas: MappingCanvasState; viewport?: CanvasTransform;
}
export interface MappingWorkspaceSnapshot {
  transfers?: import('../../core/diagrams/canvasTransfer').CanvasTransfer[];
  schemaVersion: 3; projectId: string; activeDocumentId?: string; documents: MappingDocumentSnapshot[];
}

import type { WorkspaceBatch } from '../../../domain/mapping/workspace/workspaceRecords';
import { ApplicationError } from '../../core/errors';
import type { DiagramRepository } from '../../core/ports/diagramRepository';
import type { MappingWorkspaceRepository } from './repository';
import { loadDiagramAgentContext, storeDiagramAgentContext, type DiagramAgentContext, type DiagramAgentContextStore } from '../../../domain/core/diagrams/diagramAgentContext';
import { deserializeWorkspace } from '../../../domain/mapping/workspace/mappingWorkspaceCodec';

export class MappingWorkspaceService {
  constructor(private readonly projects: Pick<DiagramRepository, 'loadProject'>, private readonly workspace: MappingWorkspaceRepository,
    private readonly diagramContexts?: DiagramAgentContextStore) { }
  async loadRecords(historyValidation: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    return this.workspace.loadRecords(project.id, historyValidation);
  }
  async loadViewHeaders() {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    return this.workspace.loadViewHeaders?.(project.id);
  }
  async applyBatch(input: WorkspaceBatch) {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    return this.workspace.applyBatch(project.id, input);
  }
  async load() {
    const project = await this.projects.loadProject();
    return project ? this.workspace.load(project.id) : null;
  }
  async save(input: unknown) {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    await this.workspace.save(project.id, input);
    return { saved: true };
  }
  /** Expand disk references at the export boundary so the JSON can be imported on another machine. */
  async portableExport(input: unknown) {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    const workspace = deserializeWorkspace(input);
    if (workspace.projectId !== project.id) throw new ApplicationError('invalid-input', 'Workspace belongs to another project');
    const expanded = new Map<string, Awaited<ReturnType<typeof loadDiagramAgentContext>>>();
    const contexts = async (values?: Record<string, DiagramAgentContext>) => {
      if (!values) return values;
      return Object.fromEntries(await Promise.all(Object.entries(values).map(async ([id, value]) => {
        const key = value.backingRecordId ?? value.snapshot?.contentHash ?? id;
        let snapshot = expanded.get(key);
        if (!snapshot) { snapshot = await loadDiagramAgentContext(value, this.diagramContexts);
          if (this.diagramContexts?.portable) snapshot = await this.diagramContexts.portable(snapshot);
          expanded.set(key, snapshot); }
        return [id, { diagramId: value.diagramId, compiledFromRevisionId: value.compiledFromRevisionId,
          sourceFingerprint: value.sourceFingerprint, contentHash: snapshot.contentHash, snapshot } satisfies DiagramAgentContext];
      })));
    };
    for (const document of workspace.documents) {
      document.document.diagramContexts = await contexts(document.document.diagramContexts);
      if (document.history) for (const checkpoint of Object.values(document.history.snapshots))
        checkpoint.document.diagramContexts = await contexts(checkpoint.document.diagramContexts);
    }
    return deserializeWorkspace(workspace);
  }
  /** Save context files before an imported workspace can publish their references. */
  async prepareImport(input: unknown) {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    if (!this.diagramContexts) throw Error('AGENT_CONTEXT_STORAGE_UNAVAILABLE');
    const workspace = deserializeWorkspace(input);
    if (workspace.projectId !== project.id) throw new ApplicationError('invalid-input', 'Workspace belongs to another project');
    const stored = new Map<string, Awaited<ReturnType<typeof storeDiagramAgentContext>>>();
    const contexts = async (values?: Record<string, DiagramAgentContext>) => {
      if (!values) return values;
      return Object.fromEntries(await Promise.all(Object.entries(values).map(async ([id, value]) => {
        if (!value.snapshot) throw Error('Workspace import requires portable diagram context snapshots');
        const key = value.snapshot.contentHash;
        let bound = stored.get(key);
        if (!bound) { bound = await storeDiagramAgentContext(value, this.diagramContexts!); stored.set(key, bound); }
        return [id, bound];
      })));
    };
    for (const document of workspace.documents) {
      document.document.diagramContexts = await contexts(document.document.diagramContexts);
      if (document.history) for (const checkpoint of Object.values(document.history.snapshots))
        checkpoint.document.diagramContexts = await contexts(checkpoint.document.diagramContexts);
    }
    return deserializeWorkspace(workspace);
  }
}

