/** The only production module that chooses and connects concrete integrations. */
export function createBackend(projectRoot: string, diagramsDirectory: string, configuredDomainProfileId: BuiltInDomainProfileId | undefined,
  mappingPocSourceRoot: string, options: { lspEnabled?: boolean; piEnabled?: boolean }) {
  const fake = process.env.NEW_DIAGRAM_AGENT === "fake";
  const chatRuntime = fake ? new FakeLocalChatRuntime() : new CodexLocalChatRuntime(options.piEnabled === true);
  const mappingRuntime = fake ? new FakeMappingAgentRuntime() : new PiMappingAgentRuntime(options.piEnabled === true);
  const store = new DiagramStore(projectRoot, diagramsDirectory);
  const contextSources = new FileAgentContextSources(store.storeRoot, async sourceId => {
    if (sourceId.startsWith('repo-')) {
      return { kind: 'git-worktree', root: await store.repositories.resolveCheckoutRoot(sourceId) };
    }
    const project = await store.loadProject();
    if (!project) throw Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE: project is not initialized');
    return (await resolveDiagramSource(store, { projectId: project.id, sourceId })).binding().corpus;
  });
  const diagramEditRuntime = fake ? new FakeDiagramEditRuntime() : new PiDiagramEditRuntime(mappingPocSourceRoot, options.piEnabled === true, contextSources);
  const core = createCoreApplication(store);
  const compactionService = createFileCompactionService(core, fake ? new FakeFileCompactionRuntime() : new PiFileCompactionRuntime(options.piEnabled === true));
  const languageService = options.lspEnabled === true ? new ProjectLanguageService() : undefined;
  const diagrams = new MappingDiagramService(store, corpusAccess, projectRoot, configuredDomainProfileId, new WorkspaceRecordStore(store.storeRoot));
  const canvasBridge = new GenerationCanvasBridge(new CanvasSessionBridge());
  const contextLibrary = new AgentContextLibrary(new FileAgentContextRepository(store.storeRoot), contextSources);
  const agentContexts = new AgentContextService(undefined, contextLibrary);
  const diagramContextStore = new FileDiagramAgentContextStore(store.storeRoot, contextSources);
  const apiProjection = new CanvasApiProjection();
  const liveCanvas = new LiveCanvasService(() => canvasBridge.list(), async (workspaceInstanceId, documentId) =>
    await canvasBridge.dispatch(workspaceInstanceId, { method: 'context', documentId }) as import('../../../domain/mapping/agent/liveCanvasStatus').LiveCanvasContext, agentContexts, apiProjection);
  const changes = new ChangeSessionService(new DiagramChangeSessionStore(store.storeRoot, undefined, true), store, canvasBridge);
  const agent = new AgentDiagrammingSessionService(canvasBridge, diagrams, store, new QuickJsAgentRuntime(),
    changes, diagramEditRuntime, agentContexts, apiProjection, diagramContextStore);
  const agentChat = new AgentChatService(new StdioCodexConnection(mappingPocSourceRoot, options.piEnabled === true), new FileChatStore(store.storeRoot), mappingPocSourceRoot, liveCanvas, new ChatDiagramTools(agent), new MappingChatMcpBinding(agent, process.cwd()), canvasBridge, contextLibrary);
  const diffSessionWorkflows = new DiffSessionWorkflowService(changes, agent, new PiDiffSessionRuntime(options.piEnabled === true),
    new FileDiffSessionRunStore(store.storeRoot), { enabled: options.piEnabled === true, sourceRoot: mappingPocSourceRoot,
      loadPrompts: loadDiffSessionPrompts, sourceReader: capture => createDiffSessionSourceReader(store.repositories, capture) });
  const pushIntegrations = new PushIntegrationService(new FilePushIntegrationStore(store.storeRoot),
    new GitPushSource(store.repositories), diffSessionWorkflows, options.piEnabled === true);
  const workspace = new MappingWorkspaceService(store, new MappingWorkspaceStore(store.storeRoot, store.diagramPersistence), diagramContextStore);
  const generatedCanvases = new GeneratedCanvasCatalog(store);
  const compareSessions = new CompareSessionService(workspace, new FileCompareSessionStore(store.storeRoot), generatedCanvases, store);
  const evalReferences = new EvalReferenceService(new JsonDirectoryStore<EvalReference>(store.storeRoot, 'eval-references'), store, new JsonDirectoryStore<EvalReferenceGroup>(store.storeRoot, 'eval-reference-groups'));
  const evalPrompts = new EvalPromptService(new JsonDirectoryStore<EvalPrompt>(store.storeRoot, 'eval-prompts'), store, evalReferences, new JsonDirectoryStore<import('../../../domain/mapping/evals/evalPrompt').PromptProjectSnapshot>(store.storeRoot, 'eval-prompt-snapshots'));
  const evalRunStore = new JsonDirectoryStore<EvalRun>(store.storeRoot, 'eval-runs');
  const evalRuns = new EvalRunService(compareSessions, workspace, store, contextLibrary, evalPrompts, generatedCanvases,
    evalRunStore, fake ? new FakeEvalRuntime() : new AgentContextEvalRuntime(projectRoot, options.piEnabled === true), new FileRollUpRunStore(store.storeRoot));
  evalRuns.layoutTemplates = new LayoutTemplateService(new JsonDirectoryStore<Awaited<ReturnType<LayoutTemplateStore['list']>>[number]>(store.storeRoot, 'layout-templates'), compareSessions, store);
  evalRuns.referenceGenerations = new ReferenceGenerationService(new JsonDirectoryStore<ReferenceGenerationSession>(store.storeRoot, 'eval-reference-sessions'), agentChat, evalRuns);
  evalRuns.replayLegacy = (run, requestId) => agentChat.rerunAlternatives(run, requestId);
  evalRuns.cancelLegacy = id => agentChat.cancelGeneration(id);
  evalRuns.readChangeSession = id => changes.get(id);
  void agentChat.observeGenerations((children, parent, historical) => evalRuns.recordLegacy(children, parent, historical)).catch(error => console.error('Generation reconciliation failed', error));
  generatedCanvases.snapshot = (id, checkpoint) => evalRuns.outputSnapshot(id, checkpoint);
  const comparisonRunStore = new FileComparisonRunStore(store.storeRoot);
  const comparisonRuns = new ComparisonGenerationService(compareSessions, comparisonRunStore, fake ? new FakeComparisonRuntime() : new CodexComparisonRuntime(options.piEnabled === true));
  evalRuns.judgements = new JudgementService(new JsonDirectoryStore<Judgement>(store.storeRoot, 'judgements'), compareSessions, comparisonRunStore, comparisonRuns, evalRunStore);
  evalRuns.experiments = new ExperimentService(new JsonDirectoryStore<StoredExperiment>(store.storeRoot, 'eval-experiments'), evalRuns, store, contextLibrary);
  evalRuns.deleteContextComparisons = (id, workflow) => comparisonRuns.deleteContextOutputs(id, workflow);
  const routes = {
    core: createCoreRoutes({
      application: core,
      source: new ProjectSourceService(store, corpusAccess, languageService),
      catalog: new ProjectCatalogService(store)
    }),
    mapping: createMappingRoutes({
      selection: new SelectionService(store, mappingRuntime, mappingPocSourceRoot),
      diagrams, agent, agentChat, liveCanvas, diffSessionWorkflows, pushIntegrations, pushToken: process.env.NEW_DIAGRAM_PUSH_TOKEN,
      workspace, compareSessions, comparisonRuns, evalRuns, evalPrompts, evalReferences,
      chat: new LocalChatService(store, corpusAccess, chatRuntime, mappingPocSourceRoot),
      compactionService
    })
  };
  return {
    routes, liveCanvas, diffSessionWorkflows, pushIntegrations, dispose() {
      comparisonRuns.dispose();
      evalRuns.dispose();
      agentChat.dispose();
      diffSessionWorkflows.dispose();
      agent.dispose(); diagramEditRuntime.dispose(); canvasBridge.dispose(); languageService?.dispose(); mappingRuntime.dispose(); chatRuntime.dispose(); compactionService.dispose();
    }
  };
}

import { canvasTypeOf, type CanvasType } from '../../../../domain/core/diagrams/canvasType';
import { DefaultCanvasHistoryService, type CanvasHistoryService } from '../../../../domain/core/diagrams/canvasHistoryService';
import { createStore } from 'zustand/vanilla';
import type { CanvasTransform } from '../../../../domain/core/diagrams/diagramCanvas';
import type { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
import { initialCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { DisplayState } from '../../../../domain/mapping/workspace/displayModel';
import type { DiagramFocus } from '../search/SearchHighlight';
import { CanvasSession, readable, type SavedDocumentState } from './canvasSession';

export interface DraftMetadata extends SavedDocumentState {
  type?: CanvasType;
  repositoryId?: string;
  hidden?: boolean; newerRevision?: boolean; reloadKey?: string; representationId?: string;
  revisionId: string; busy: boolean; viewport?: CanvasTransform; focusBox?: DiagramFocus;
}
export interface CanvasDraft extends DraftMetadata { session: CanvasSession }
export type CanvasDraftSeed = DraftMetadata & Pick<ConstructorParameters<typeof CanvasSession>[0], 'document' | 'canvas' | 'history'>;
type DraftInput = CanvasDraft | CanvasDraftSeed;
type Drafts = Record<string, CanvasDraft>;

/** Registry owns session lifetimes. Page state contains metadata and stable handles only. */
export class CanvasWorkspace {
  private readonly storeState = createStore(() => ({ drafts: {} as Drafts }));
  readonly controllers = new Map<string, MappingDocumentController>();
  private readonly changesState = createStore(() => ({ version: 0 }));
  private readonly dirtyScenesState = createStore(() => ({ ids: [] as string[] }));
  readonly store = readable(this.storeState);
  readonly changes = readable(this.changesState);
  readonly dirtyScenes = readable(this.dirtyScenesState);
  private subscriptions = new Map<string, (() => void)[]>();
  constructor(private readonly history: CanvasHistoryService = new DefaultCanvasHistoryService()) {}
  private persistenceListeners = new Set<(ids: string[]) => void>();
  onPersist(listener: (ids: string[]) => void) { this.persistenceListeners.add(listener); return () => { this.persistenceListeners.delete(listener); }; }
  private persist(ids: string[]) { this.persistenceListeners.forEach(listener => listener(ids)); }
  private changed = () => this.changesState.setState(s => ({ version: s.version + 1 }));
  private refreshDirty = () => {
    const ids = Object.entries(this.store.getState().drafts).filter(([, d]) => d.session.status.getState().sceneDirty).map(([id]) => id);
    const prior = this.dirtyScenes.getState().ids;
    if (ids.length !== prior.length || ids.some((id, i) => id !== prior[i])) this.dirtyScenesState.setState({ ids });
  };
  copyDocument(input: { repositoryId?: string; documentId: string; name: string; expectedVersion?: number; display?: DisplayState; viewport?: CanvasTransform }) {
    const source = this.store.getState().drafts[input.documentId];
    if (!source || source.hidden) throw new Error('DOCUMENT_UNAVAILABLE');
    if (source.busy) throw new Error('DOCUMENT_BUSY');
    const name = input.name.trim();
    if (!name || name.length > 120) throw new Error('Expected a canvas name between 1 and 120 characters');
    const controller = source.session.controller, snapshot = controller.getSnapshot();
    if (input.expectedVersion !== undefined && input.expectedVersion !== snapshot.version) throw new Error('VERSION_CONFLICT: read the source canvas again');
    const canvas = structuredClone({ ...snapshot.canvas, display: input.display ?? snapshot.canvas.display, selection: { items: [] }, controls: initialCanvasState().controls });
    // A copied conversation retains its messages, but has no running request.
    for (const node of Object.values(canvas.display.nodes)) if (node.kind === 'conversation') node.thread.pending = false;
    const documentId = `draft-${crypto.randomUUID()}`;
    this.setDrafts(current => ({ ...current, [documentId]: {
      type: source.type, name, repositoryId: input.repositoryId ?? source.repositoryId, savedName: '', revisionId: '', busy: false, document: snapshot.document, canvas,
      history: controller.forkHistory(canvas), viewport: structuredClone(input.viewport ?? source.viewport),
      savedScene: JSON.stringify(snapshot.document.scene), savedEdges: JSON.stringify(snapshot.document.edges)
    } }));
    return { documentId };
  }
  setDrafts = (value: Record<string, DraftInput> | ((current: Drafts) => Record<string, DraftInput>)) => {
    const prior = this.store.getState().drafts;
    const input = typeof value === 'function' ? value(prior) : value;
    if (input === prior) return;
    const next: Drafts = {};
    let persist = false;
    const changedIds = new Set<string>();
    for (const [id, item] of Object.entries(input)) {
      if (item === prior[id]) { next[id] = prior[id]; continue; }
      if ('document' in item) {
        const { document, canvas, history, ...metadata } = item;
        next[id] = { ...metadata, type: canvasTypeOf({ ...metadata, canvas }), session: new CanvasSession({ ...metadata, document, canvas, history }, this.history) };
      } else next[id] = item;
      next[id].session.updateBaseline(next[id]);
      const old = prior[id];
      if (!old || next[id].session !== old.session || ['name', 'savedName', 'savedScene', 'savedEdges', 'revisionId', 'representationId', 'repositoryId', 'type', 'hidden'].some(key =>
        old[key as keyof DraftMetadata] !== next[id][key as keyof DraftMetadata])) { persist = true; changedIds.add(id); }
    }
    for (const [id, old] of Object.entries(prior)) if (next[id]?.session !== old.session) {
      this.subscriptions.get(id)?.forEach(unsubscribe => unsubscribe()); this.subscriptions.delete(id);
      this.controllers.delete(id); old.session.dispose(); persist = true; changedIds.add(id);
    }
    for (const [id, draft] of Object.entries(next)) if (!this.subscriptions.has(id)) {
      const session = draft.session;
      this.controllers.set(id, session.controller);
      this.subscriptions.set(id, [session.onCommit(() => { this.changed(); this.persist([id]); }), session.status.subscribe(this.refreshDirty), session.document.subscribe(() => {
        // Document consumers (search/explorer) get a new entry; presentation/interaction never enter this path.
        const current = this.store.getState().drafts;
        if (current[id]?.session === session) this.storeState.setState({ drafts: { ...current, [id]: { ...current[id] } } });
      })]);
    }
    this.storeState.setState({ drafts: next });
    this.refreshDirty();
    if (persist) { this.changed(); this.persist([...changedIds]); }
  };
  dispose() { this.subscriptions.forEach(list => list.forEach(off => off())); this.persistenceListeners.clear(); Object.values(this.store.getState().drafts).forEach(d => d.session.dispose()); }
}

import type { DiagramPresentations } from '../../core/presentation/diagramPresentation';
import { createStoredDiagram } from '../../core/diagrams/diagramRevisionStore';

import {
  layoutScene,
  updateGridBox,
  type Diagram,
  type GridBox,
  type LineGridScene
} from "../../core/diagrams/lineGrid";
import { MAPPING_POC_A_NODES, MAPPING_POC_GRAPH_A } from "../selection/mappingPoc";
import { MAPPING_POC_A_SECTIONS, type MappingPocASection } from "../selection/mappingPocOverlays";

export interface MappingGridDocument {
  alternatives?: import('../../core/presentation/diagramAlternative').DiagramAlternatives;
  diagramPresentations?: DiagramPresentations;
  diagramContexts?: Record<string, import('../../core/diagrams/diagramAgentContext').DiagramAgentContext>;
  revisionSelections?: Record<string, import('../../core/diagrams/diagramRevisionSelection').DiagramRevisionSelection>;
  revisionReviews?: Record<string, import('../../core/diagrams/diagramRevisionReview').DiagramRevisionReview>;
  jumps?: import('../../core/diagrams/canvasJump').CanvasJump[];
  scene: LineGridScene;
  edges: import('../../core/diagrams/diagramConnection').DiagramConnection[];
  sections: Readonly<Record<string, readonly MappingPocASection[]>>;
}

export function initialMappingGrid(): MappingGridDocument {
  const evidence = Object.fromEntries(MAPPING_POC_A_NODES.map(node => [node.id, { id: node.id, handle: node.id, label: node.label, category: "operation" as const, summary: node.label, sourceRanges: node.sourceRanges.map((range,i) => ({ ...range, id: `${node.id}-range-${i}`, originalLines: Array.from({length:range.endLine-range.startLine+1},()=>"") })) }]));
  const content = createStoredDiagram({ evidence,
    id: "overview", revision: 0, ascii: MAPPING_POC_GRAPH_A,
    mappings: MAPPING_POC_A_NODES.flatMap((node) => node.sourceRanges.map((_, sourceRangeIndex) => ({
      id: `${node.id}:range-${sourceRangeIndex + 1}`, entityId: node.id, sourceRangeIndex,
      ...node.head
    })))
  }).diagram;
  return {
    edges: [],
    scene: { contents: { overview: content, "overview-summary": createStoredDiagram({ id: "overview-summary", revision: 0, ascii: "[Current LLM prompt stack]" }).diagram },
      root: { id: "root", kind: "container", position: { column: 0, row: 0 }, collapsed: false,
        layout: { collisionPolicy: "push-right", gap: 3 }, children: [{ id: "overview", kind: "diagram",
          position: { column: 0, row: 0 }, collapsed: false, contentId: "overview", collapsedContentId: "overview-summary" }] }
    },
    sections: { overview: MAPPING_POC_A_SECTIONS }
  };
}

export function insertGridDiagram(document: MappingGridDocument, parentId: string, box: GridBox, content: Diagram): MappingGridDocument {
  const summaryId = `${content.id}-summary`;
  let scene: LineGridScene = { ...document.scene, contents: { ...document.scene.contents, [content.id]: content,
    [summaryId]: createStoredDiagram({ id: summaryId, revision: 0, ascii: `[${content.content.ascii.split("\n")[0].trim().slice(0, 36)}]` }).diagram } };
  scene = updateGridBox(scene, parentId, (parent) => {
    if (parent.kind !== "container") throw new Error("Diagrams must be inserted into a container");
