  dispose() { this.cursorCopy.clear(); this.unsubscribe(); this.commitListeners.clear(); }
}

import type { StorageChange } from '../../../../domain/core/storage/storageService';
import { canvasViewChanges, documentPrefix, historyChanges, type WorkspaceIndex } from '../../../../domain/mapping/workspace/workspaceRecords';
import type { CanvasTransfer } from '../../../../domain/core/diagrams/canvasTransfer';
import type { StoredCanvasSnapshot } from '../../../../domain/core/diagrams/canvasHistory';
import { isCheckpointDelta } from '../../../../domain/core/diagrams/canvasCheckpointRecords';
import type { CanvasDraft, CanvasWorkspace } from './canvasWorkspace';
import type { CanvasSession } from './canvasSession';
import type { SourcePaneViewState } from '../source-pane/sourcePaneViewState';
import type { RecordStorage } from './recordStorage';

/** Owns the translation from live owners to persisted records, never a global snapshot. */
export class WorkspacePersistence {
  private cursors = new WeakMap<CanvasSession, number>();
  private known = new Map<string, CanvasDraft>();
  private subscriptions: (() => void)[] = [];
  private activeDocumentId?: string;
  private transfers: CanvasTransfer[] = [];
  private paused = false;
  constructor(private readonly workspace: CanvasWorkspace, private readonly storage: RecordStorage,
    private readonly projectId: string, private readonly view: SourcePaneViewState) {
    const index = storage.get<WorkspaceIndex>('workspace');
    this.activeDocumentId = index?.activeDocumentId; this.transfers = index?.transfers ?? [];
    this.subscriptions.push(workspace.onPersist(ids => this.sync(ids)), view.subscribe(id => this.syncView(id)));
    this.sync([...new Set([...(index?.documentIds ?? []), ...Object.keys(workspace.store.getState().drafts)])]);
  }
  setPaused(paused: boolean) { this.paused = paused; }
  update(activeDocumentId: string | undefined, transfers: CanvasTransfer[]) {
    this.activeDocumentId = activeDocumentId; this.transfers = transfers;
    if (!this.paused) this.storage.batch([this.index()]);
  }
  private index(): StorageChange {
    const ids = Object.keys(this.workspace.store.getState().drafts);
    return { key: 'workspace', value: { projectId: this.projectId, documentIds: ids,
      activeDocumentId: this.activeDocumentId && ids.includes(this.activeDocumentId) ? this.activeDocumentId : ids[0], transfers: this.transfers } satisfies WorkspaceIndex };
  }
  sync(ids = [...new Set([...this.known.keys(), ...Object.keys(this.workspace.store.getState().drafts)])]) {
    if (this.paused) return;
    const drafts = this.workspace.store.getState().drafts, changes: StorageChange[] = [];
    for (const id of ids) {
      const draft = drafts[id], prior = this.known.get(id), prefix = documentPrefix(id);
      if (!draft) {
        for (const key of this.storage.keys()) if (key.startsWith(prefix)) changes.push({ key, delete: true });
        this.known.delete(id); continue;
      }
      const { representationId: savedRepresentationId, name, hidden, repositoryId, type, savedName, savedScene, savedEdges, revisionId } = draft;
      changes.push({ key: prefix + 'metadata', value: { representationId: id, savedRepresentationId, repositoryId, type, name, hidden, version: draft.session.controller.getSnapshot().version } },
        { key: prefix + 'baseline', value: { savedName, savedScene, savedEdges, revisionId } });
      const cursor = this.cursors.get(draft.session), delta = draft.session.controller.persistenceChanges(cursor);
      if (cursor === undefined) {
        // Import/reset can replace a canvas's history graph under the same ID.
        // Remove the old graph in the same atomic batch as its replacement.
        const retained = new Set(historyChanges(id, delta).map(change => change.key));
        for (const key of this.storage.keys()) {
          if ((key.startsWith(prefix + 'revision/') || key.startsWith(prefix + 'checkpoint/')) && !retained.has(key)) changes.push({ key, delete: true });
        }
      }
      for (const change of historyChanges(id, delta)) {
        // A new runtime session may attach to history already present in storage.
        // Revision IDs are immutable; checkpoints may have retired transfer links.
        if (cursor === undefined && 'value' in change && this.storage.get(change.key)) {
          if (change.key.startsWith(prefix + 'revision/')) continue;
          const previous = this.storage.get<StoredCanvasSnapshot>(change.key);
          if (change.key.startsWith(prefix + 'checkpoint/') && isCheckpointDelta(previous)
            && JSON.stringify(previous) === JSON.stringify(change.value)) continue;
        }
        changes.push(change);
      }
      this.cursors.set(draft.session, delta.sequence);
      const canvas = draft.session.controller.getSnapshot().canvas;
      changes.push(...canvasViewChanges(id, { ...canvas, display: this.view.captureDisplay(id, canvas.display) }));
      if (prior?.viewport !== draft.viewport || !prior) {
        const viewport = this.view.captureCamera(id, draft.viewport);
        if (viewport) changes.push({ key: prefix + 'viewport', value: viewport });
      }
      this.known.set(id, draft);
    }
    changes.push(this.index()); this.submit(changes);
  }
  private syncView(id: string) {
    if (this.paused) return;
    const draft = this.workspace.store.getState().drafts[id]; if (!draft) return;
    const prefix = documentPrefix(id), canvas = draft.session.controller.getSnapshot().canvas;
    const viewport = this.view.captureCamera(id, draft.viewport);
    this.submit([...canvasViewChanges(id, { ...canvas, display: this.view.captureDisplay(id, canvas.display) }),
      ...(viewport ? [{ key: prefix + 'viewport', value: viewport }] : [])]);
  }
  private submit(changes: StorageChange[]) {
    // Content-addressed items are immutable and may be shared by view and history.
    // Sending them once avoids retransmitting unchanged panels on every gesture.
    const unique = new Map(changes.map(change => [change.key, change]));
    this.storage.batch([...unique.values()].filter(change => !change.key.includes('/item/') || 'delete' in change || !this.storage.get(change.key)));
  }
  dispose() { this.subscriptions.forEach(off => off()); }
}

import type { StorageChange } from '../../../../domain/core/storage/storageService';
import type { MappingDocumentSnapshot, MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { documentRecords, documentPrefix, type WorkspaceIndex, type WorkspaceRecordState } from '../../../../domain/mapping/workspace/workspaceRecords';
import { RecordStorage } from './recordStorage';

/** One worker per opened workspace; no worker construction in a store() call. */
export class WorkspaceStorage {
  records?: RecordStorage;
  private worker?: Worker;
  private id = 0;
  private requests = new Map<number, { resolve(value: unknown): void; reject(error: Error): void }>();
  private endpoint = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/workspace/records`;
  private ready?: Promise<MappingWorkspaceSnapshot | null>;
  private ensureWorker() {
    if (this.worker) return this.worker;
    const worker = this.worker = new Worker(new URL('./workspaceStorage.worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = ({ data }) => {
      const request = this.requests.get(data.id); if (!request) return;
      this.requests.delete(data.id);
      if (data.error) request.reject(Error(data.error)); else request.resolve(data.result);
    };
    const fail = () => {
      this.requests.forEach(r => r.reject(Error('Workspace worker stopped; reload to reconnect'))); this.requests.clear();
      worker.terminate(); this.worker = undefined;
    };
    worker.onerror = fail; worker.onmessageerror = fail;
    return worker;
  }
  private request<T>(input: Record<string, unknown>): Promise<T> {
    return new Promise((resolve, reject) => {
      const id = ++this.id;
      this.requests.set(id, { resolve: value => resolve(value as T), reject });
      try { this.ensureWorker().postMessage({ ...input, id, endpoint: new URL(this.endpoint, location.href).href }); }
      catch (e) { this.requests.delete(id); reject(e); }
    });
  }
  load() {
    return this.ready ??= this.request<{ state: WorkspaceRecordState; workspace: MappingWorkspaceSnapshot | null }>({ type: 'load' }).then(({ state, workspace }) => {
      this.records = new RecordStorage(state, { write: batch => this.request({ type: 'write', batch }) }); return workspace;
    }).catch(error => { this.ready = undefined; throw error; });
  }
  async project(snapshot: MappingWorkspaceSnapshot) { return this.request<StorageChange[]>({ type: 'project', snapshot }); }
  async save(snapshot: MappingWorkspaceSnapshot) {
    await this.load(); await this.records!.flush();
    const changes = await this.project(snapshot);
    await this.records!.commit(changes);
  }

  /** Publish one canvas atomically without exporting/revalidating unrelated histories. */
  async saveDocument(document: MappingDocumentSnapshot, index: WorkspaceIndex, create = false) {
    await this.load(); await this.records!.flush();
    if (create && this.records!.get(documentPrefix(document.representationId) + 'metadata')) throw Error('Canvas already exists');
    await this.records!.commit([
      ...Object.entries(documentRecords(document)).map(([key, value]) => ({ key, value })),
      { key: 'workspace', value: index }
    ]);
  }

  async restore() {
    await this.records?.flush();
    this.records?.dispose(); this.ready = undefined;
    return this.load();
  }
  async flush() { await this.load(); await this.records!.flush(); }
  dispose() {
    this.records?.dispose(); this.worker?.terminate(); this.worker = undefined;
    this.requests.forEach(r => r.reject(Error('Storage closed'))); this.requests.clear();
  }
}

import { CanvasHistory, type CanvasHistoryRecord, type ResolvedCanvasDocument } from './canvasHistory';
import type { DiagramView } from './diagramRevisionEditor';
import { prepareCanvasTransfer, prepareTransferNavigation, transferBoundary, type CanvasTransfer, type TransferInput, type PreparedCanvasTransfer, type TransferState } from './canvasTransfer';


/** Runtime handle. Neither it nor the service belongs in a saved canvas. */
export interface CanvasEditingContext { readonly contextId: string }
export interface CanvasContextState {
  checkpointId: string;
  document: import('./canvasHistory').CanvasDocument;
  view: unknown;
  canUndo: boolean;
  canRedo: boolean;
}

/** Canvas controllers coordinate edits; this boundary owns history and its storage. */
export interface CanvasHistoryService {
  startGeneration(context: CanvasEditingContext, parentId: string, candidates: { id: string; name: string; generation: import('./canvasGeneration').CanvasGeneration }[], pinned?: CanvasHistoryRecord): CanvasHistoryRecord;
  updateGeneration(context: CanvasEditingContext, viewId: string, generation: import('./canvasGeneration').CanvasGeneration, proposed?: CanvasHistoryRecord): void;

  canvasViewComparison(context: CanvasEditingContext, viewId: string): import('./canvasView').CanvasViewComparison;
  canvasViews(context: CanvasEditingContext): import('./canvasView').CanvasViewState;
  canvasView(context: CanvasEditingContext, input: import('./canvasView').CanvasViewCommand, view?: unknown): import('./canvasView').CanvasViewState;
  navigation?(context: CanvasEditingContext): import('./canvasHistory').CanvasHistoryNavigation;
  prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext): PreparedCanvasTransfer;
  transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo?: boolean): boolean;
  prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo?: boolean): { source: TransferState; destination: TransferState; transaction: CanvasTransfer };
  openContext(document: ResolvedCanvasDocument, view: unknown, history?: CanvasHistoryRecord): CanvasEditingContext;
  state(context: CanvasEditingContext): CanvasContextState;
  resolve(context: CanvasEditingContext, diagramId: string): DiagramView;
  document(context: CanvasEditingContext): ResolvedCanvasDocument;
  append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>): void;
  navigate(context: CanvasEditingContext, redo?: boolean): boolean;
  reset(context: CanvasEditingContext): void;
  /** Portable transport adapters; callers must not interpret diagram revision tables. */
  exportContext(context: CanvasEditingContext, currentOnly?: boolean): CanvasHistoryRecord;
  persistenceChanges(context: CanvasEditingContext, since?: number): import("./canvasHistory").HistoryChanges;
  retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>): void;
  forkContext(context: CanvasEditingContext, view: unknown): CanvasHistoryRecord;
  adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord): void;
}

export class DefaultCanvasHistoryService implements CanvasHistoryService {
  canvasViewComparison(context: CanvasEditingContext, viewId: string) { return this.history(context).canvasViewComparison(viewId); }
  startGeneration(context: CanvasEditingContext, parentId: string, candidates: { id: string; name: string; generation: import('./canvasGeneration').CanvasGeneration }[], pinned?: CanvasHistoryRecord) { return this.history(context).startGeneration(parentId, candidates, pinned); }
  updateGeneration(context: CanvasEditingContext, viewId: string, generation: import('./canvasGeneration').CanvasGeneration, proposed?: CanvasHistoryRecord) { this.history(context).updateGeneration(viewId, generation, proposed); }
  canvasViews(context: CanvasEditingContext) { return this.history(context).canvasViews(); }
  canvasView(context: CanvasEditingContext, input: import('./canvasView').CanvasViewCommand, view?: unknown) { return this.history(context).canvasView(input, view); }
  constructor(private readonly validation: import('./canvasHistory').HistoryValidation = 'all') {}
  // Object handles isolate two viewers of the same persisted context, and allow GC on close.
  private readonly contexts = new WeakMap<CanvasEditingContext, CanvasHistory>();

  openContext(document: ResolvedCanvasDocument, view: unknown, record?: CanvasHistoryRecord): CanvasEditingContext {
    const history = new CanvasHistory(document, view, record, this.validation);
    const context = Object.freeze({ contextId: history.contextId });
    this.contexts.set(context, history);
    return context;
  }
  private history(context: CanvasEditingContext) {
    const history = this.contexts.get(context);
    if (!history) throw new Error('Unknown diagram editing context');
    return history;
  }
  state(context: CanvasEditingContext): CanvasContextState {
    const history = this.history(context), head = history.head;
    return { checkpointId: head.id, document: head.document, view: head.view, canUndo: history.canUndo, canRedo: history.canRedo };
  }
  resolve(context: CanvasEditingContext, diagramId: string) {
    const history = this.history(context);
    return history.diagrams.resolve(history.contextId, diagramId);
  }
  document(context: CanvasEditingContext) { return this.history(context).document(); }
  append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>) {
    this.history(context).append(document, view, correspondence);
  }
  navigate(context: CanvasEditingContext, redo = false) {
    const linked = this.history(context).navigationTransactionId(redo);
    if (linked) throw Error('Use workspace undo/redo for a canvas transfer.');
    return !!this.history(context).navigate(redo);
  }
  prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext) {
    return prepareCanvasTransfer(this.history(context).export(), input, destination ? this.history(destination).export() : undefined);
  }
  transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo = false) {
    return transferBoundary({ headId: this.history(context).headId }, transaction, canvasId, redo);
  }
  prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo = false) {
    return prepareTransferNavigation(this.history(source).export(), this.history(destination).export(), transaction, redo);
  }
  reset(context: CanvasEditingContext) { this.history(context).reset(); }
  persistenceChanges(context: CanvasEditingContext, since?: number) { return this.history(context).persistenceChanges(since); }
  retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>) { this.history(context).retireTransactions(ids); }
  exportContext(context: CanvasEditingContext, currentOnly = false) { return this.history(context).export(currentOnly); }
  navigation(context: CanvasEditingContext) { return this.history(context).navigation(); }
  forkContext(context: CanvasEditingContext, view: unknown) { return this.history(context).fork(view); }
  adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord) { this.history(context).adopt(proposed); }
}

import { canvasReply, mutationCommands } from '../../../../domain/mapping/agent/canvasReply';
import { publishLiveCanvasSelections, type LiveAgentStatus } from './liveCanvasPublisher';
import type { CanvasWorkspace } from '../workspace/canvasWorkspace';
import { useEffect, useRef, useState } from 'react';
import type { CanvasCommand, CanvasDescriptor } from '../../../../domain/mapping/agent/contracts';
import { apiFetch, errorFrom } from '../../../shared/http/http';
import { browserStableWorkspaceId } from './stableWorkspaceIdentity';

export function useAgentCanvasBridge(descriptor: Omit<CanvasDescriptor, 'canvasId' | 'stableWorkspaceId'>, handle: (command: CanvasCommand) => Promise<unknown>, workspace?: CanvasWorkspace, canMutate: () => boolean = () => true) {
  const [agentStatus, setAgentStatus] = useState<LiveAgentStatus>({ connected: false, count: 0 });
  const [canvasId] = useState(() => crypto.randomUUID());
  const [identity, setIdentity] = useState<{ stableWorkspaceId?: string }>();
  useEffect(() => {
    let active = true;
    void browserStableWorkspaceId(import.meta.env.BASE_URL).then(stableWorkspaceId => {
      if (active) setIdentity({ stableWorkspaceId });
    });
    return () => { active = false; };
  }, []);
  const latest = useRef({ descriptor, handle, canMutate }); latest.current = { descriptor, handle, canMutate };
  const registration = identity && JSON.stringify({ ...descriptor, canvasId, ...identity });
  useEffect(() => {
    if (!registration) return;
    void apiFetch('/api/mapping/agent/canvases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: registration }).catch(() => undefined);
  }, [registration]);
  useEffect(() => {
    if (!identity) return;
    const abort = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const results = new Map<string, { value?: unknown; error?: string }>();
    const request = async (path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST') => {
      const response = await apiFetch(`/api/mapping/agent${path}`, { method, signal: abort.signal,
        ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
      if (!response.ok) throw await errorFrom(response);
      return response.json();
    };
    const register = () => request('/canvases', { ...latest.current.descriptor, canvasId, ...identity });
    const run = async () => {
      try {
        await register();
        while (!abort.signal.aborted) {
          const commands: CanvasCommand[] = await request(`/canvases/${canvasId}/commands`);
          for (const command of commands) {
            const started = performance.now();
            let result = results.get(command.id);
            if (!result) {
              try { result = { value: await latest.current.handle(command) }; }
              catch (error) { result = { error: error instanceof Error ? error.message : String(error) }; }
              if (mutationCommands.has(command.method)) results.set(command.id, result);
              if (results.size > 200) results.delete(results.keys().next().value!);
            }
            const handled = performance.now();
            const reply = canvasReply(command, result);
            const encoded = performance.now();
            const response = await apiFetch(`/api/mapping/agent/canvases/${canvasId}/reply`, { method: 'POST', signal: abort.signal,
              headers: { 'content-type': 'application/json', 'x-canvas-command-id': command.id }, body: reply.body });
            if (!response.ok) {
              // A proxy/backend can enforce a lower limit. Resolve the pending command immediately.
              await request(`/canvases/${canvasId}/reply`, { commandId: command.id,
                error: `CANVAS_REPLY_REJECTED: method=${command.method} actualBytes=${reply.bytes} status=${response.status}; retry the identical requestId if this was a mutation` });
            }
            console.debug('canvas-reply', { method: command.method, bytes: reply.bytes, handleMs: Math.round(handled - started), encodeMs: Math.round(encoded - handled), replyMs: Math.round(performance.now() - encoded), durationMs: Math.round(performance.now() - started), oversized: reply.oversized });
          }
          await register();
        }
      } catch {
        if (!abort.signal.aborted) timer = setTimeout(() => void run(), 1000);
      }
    };
    void run();
    const unregister = () => { void apiFetch(`/api/mapping/agent/canvases/${canvasId}`, { method: 'DELETE', keepalive: true }).catch(() => undefined); };
    // React cleanup does not run on page reload. Retire this ephemeral instance
    // promptly, without ever deleting a replacement that has the same stable ID.
    window.addEventListener('pagehide', unregister);
    return () => { abort.abort(); clearTimeout(timer); window.removeEventListener('pagehide', unregister); unregister(); };
  }, [canvasId, identity]);
  useEffect(() => {
    setAgentStatus({ connected: false, count: 0 });
    if (!workspace || !identity) return;
    const endpoint = new URL(`${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/live`, location.href);
    endpoint.protocol = endpoint.protocol === 'https:' ? 'wss:' : 'ws:';
    return publishLiveCanvasSelections(workspace, canvasId, endpoint.href, setAgentStatus, () => latest.current.canMutate());
  }, [workspace, canvasId, identity]);
  return { canvasId, agentStatus };
}

