import { WorkspaceRecordStore } from './workspaceRecordStore';
import type { WorkspaceBatch } from '../../../../domain/mapping/workspace/workspaceRecords';
import { DiagramPersistence } from '../../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from '../../../core/persistence/diagramRevisionStore';
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { deserializeWorkspace } from '../../../../domain/mapping/workspace/mappingWorkspaceCodec';
/** Separate from representation revisions: UI changes do not create diagram revisions. */
export class MappingWorkspaceStore {
  constructor(private readonly root: string, private readonly diagramPersistence: DiagramPersistence = new DiagramPersistence(new DiagramRevisionStore(root))) { this.records = new WorkspaceRecordStore(root); }
  private readonly records: WorkspaceRecordStore;
  loadRecords(projectId: string, historyValidation: import('../../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') { return this.records.state(projectId, () => this.loadLegacy(projectId), historyValidation); }
  loadViewHeaders(projectId: string) { return this.records.viewHeaders(projectId); }
  applyBatch(projectId: string, batch: WorkspaceBatch) { return this.records.apply(projectId, batch); }
  async load(projectId: string): Promise<MappingWorkspaceSnapshot | null> {
    return await this.records.load(projectId) ?? this.loadLegacy(projectId);
  }
  private async loadLegacy(projectId: string): Promise<MappingWorkspaceSnapshot | null> {
    let json: string;
    try { json = await readFile(path.join(this.root, 'mapping-workspace.json'), 'utf8'); }
    catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
    // A missing referenced diagram is corruption, not a missing workspace.
    const snapshot = deserializeWorkspace(await this.diagramPersistence.restore(JSON.parse(json)));
    if (snapshot.projectId !== projectId) throw new Error('Workspace belongs to another project');
    return snapshot;
  }

  async save(projectId: string, input: unknown): Promise<void> {
    const snapshot = deserializeWorkspace(input);
    if (snapshot.projectId !== projectId) throw new Error('Workspace belongs to another project');
    if (await this.records.replace(projectId, snapshot)) return;
    const json = JSON.stringify(await this.diagramPersistence.persist(snapshot));
    await mkdir(this.root, { recursive: true });
    const temp = path.join(this.root, `.mapping-workspace-${randomUUID()}.tmp`);
    try { await writeFile(temp, json, 'utf8'); await rename(temp, path.join(this.root, 'mapping-workspace.json')); }
    finally { await rm(temp, { force: true }); }
  }
}

import type { SaveProjectDiagramInput } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { BuiltInDomainProfileId } from '../../../domain/core/profiles/domainProfile';
import type { CorpusAccess } from '../../core/corpus/corpusAccess';
import type { DiagramRepository } from '../../core/ports/diagramRepository';
import { assertSafeId } from '../../../domain/core/records/domain';
import { ApplicationError } from '../../core/errors';

export class MappingDiagramService {
  constructor(private readonly projects: Pick<DiagramRepository, 'loadProject' | 'ensureProject' | 'projectCatalogs'>,
    private readonly corpus: CorpusAccess, private readonly root: string,
    private readonly profile: BuiltInDomainProfileId = 'source-code',
    private readonly checkpoints?: { capture(projectId: string, documentId: string, checkpointId: string, version: number): Promise<import('../../../domain/core/diagrams/checkpointPublication').CapturedCheckpoint> }) { }
  async initialize() {
    const project = await this.projects.loadProject() ?? await this.projects.ensureProject({ checkoutRoot: this.root, repositoryIdentity: "", domainProfileId: this.profile });
    return { project, catalog: await this.projects.projectCatalogs.loadRepresentationCatalog(project.id) };
  }
  async save(input: SaveProjectDiagramInput) {
    const project = await this.projects.loadProject() ?? await this.projects.ensureProject({ checkoutRoot: this.root, repositoryIdentity: "", domainProfileId: this.profile });
    return { project, ...await this.projects.projectCatalogs.saveMappingDiagram(project.id, input) };
  }
  async publishCheckpoint(input: import('../../../domain/core/diagrams/checkpointPublication').CheckpointPublication) {
    const project = await this.projects.loadProject();
    if (!project || !this.projects.projectCatalogs.publishCheckpoint || !this.checkpoints) throw Error('WORKSPACE_UNAVAILABLE: checkpoint publication unavailable');
    return this.projects.projectCatalogs.publishCheckpoint(project.id, input, () => this.checkpoints!.capture(project.id, input.documentId, input.checkpointId, input.expectedVersion));
  }
  async delete(representationId: string) {
    assertSafeId(representationId);
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    const catalog = await this.projects.projectCatalogs.archiveRepresentation(project.id, representationId);
    return { project, catalog };
  }
}
